def total_minutes(minutes_per_session, sessions):
    return minutes_per_session * sessions

name = input().strip()
if name == '':
    name = 'Learner'
minutes = int(input())
sessions = int(input())
if minutes <= 0 or sessions <= 0:
    print('Enter positive numbers.')
else:
    total = total_minutes(minutes, sessions)
    print(f'{name}: {sessions} sessions, {total} minutes total.')
    for number in range(1, sessions + 1):
        print(f'Session {number}')
